<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\SoftDeletes;use Illuminate\Support\Str;class Service extends Model{use SoftDeletes;public $incrementing=false;protected $keyType='string';protected $fillable=['category_id','title','short_description','description','image_url','status','created_by'];protected static function booted(){static::creating(fn($m)=>$m->id??=(string)Str::uuid());}public function category(){return $this->belongsTo(ServiceCategory::class,'category_id');}public function media(){return $this->hasMany(ServiceMedia::class);}}
